void reverse(Node* head) {
    if (head == nullptr || head->next == nullptr)
        return;

    Node* prev = nullptr;
    Node* current = head;
    while (current != nullptr) {
        Node* next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }
    head = prev;
}
